@code {
    [Parameter, EditorRequired]
    public List<Course> Courses { get; set; } = [];
}

@inject ICatalogService CatalogService

@if (submitted)
{
    <div class="alert @(success ? "alert-success" : "alert-danger")">
        @if (success)
        {
            <h5>✅ Enrollment Request Submitted</h5>
            <p class="mb-0">Your enrollment request for <strong>@selectedCourseTitle</strong> has been received. You will be notified by email once processed.</p>
        }
        else
        {
            <h5>❌ Enrollment Failed</h5>
            <p class="mb-0">@errorMessage</p>
        }
    </div>
    <button class="btn btn-outline-primary" @onclick="Reset">Submit Another Request</button>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <InputText id="studentName" class="form-control" @bind-Value="model.StudentName" required />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" class="form-control" placeholder="e.g., STU-12345" @bind-Value="model.StudentId" required />
        </div>

        <div class="mb-3">
            <label for="courseSelect" class="form-label">Course</label>
            <InputSelect id="courseSelect" class="form-select" @bind-Value="model.CourseId">
                <option value="0">— Select a course —</option>
                @foreach (var course in Courses)
                {
                    <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr.)</option>
                }
            </InputSelect>
        </div>

        <button type="submit" class="btn btn-primary" disabled="@(!IsValid)">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    [Parameter] public int? PreselectedCourseId { get; set; }

    private EnrollmentRequest model = new();
    private List<Course> Courses = [];
    private bool submitted;
    private bool success;
    private string selectedCourseTitle = "";
    private string errorMessage = "";

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(model.StudentName) &&
        !string.IsNullOrWhiteSpace(model.StudentId) &&
        model.CourseId > 0;

    protected override async Task OnInitializedAsync()
    {
        Courses = await CatalogService.GetCoursesAsync();
        if (PreselectedCourseId.HasValue)
            model.CourseId = PreselectedCourseId.Value;
    }

    private async Task HandleSubmit()
    {
        if (!IsValid) return;

        var course = Courses.FirstOrDefault(c => c.Id == model.CourseId);
        selectedCourseTitle = course is not null ? $"{course.Code} — {course.Title}" : "Unknown";

        success = await CatalogService.SubmitEnrollmentAsync(model);
        if (!success)
            errorMessage = course is not null && course.CurrentEnrollment >= course.MaxEnrollment
                ? "This course is currently full. Please try another course or check back later."
                : "The selected course was not found. Please select a valid course.";

        submitted = true;
    }

    private void Reset()
    {
        model = new();
        if (PreselectedCourseId.HasValue)
            model.CourseId = PreselectedCourseId.Value;
        submitted = false;
        success = false;
    }
}

