@code {
    [Parameter] public List<Department> Departments { get; set; } = [];
    [Parameter] public EventCallback<(string? Search, int? DepartmentId)> OnFiltersChanged { get; set; }

    private string searchText = "";
    private int selectedDepartmentId;

    private async Task OnFilterChanged()
    {
        int? deptId = selectedDepartmentId == 0 ? null : selectedDepartmentId;
        var search = string.IsNullOrWhiteSpace(searchText) ? null : searchText;
        await OnFiltersChanged.InvokeAsync((search, deptId));
    }

    private async Task ClearSearch()
    {
        searchText = "";
        await OnFilterChanged();
    }
}
