@page "/courses"

@inject ICatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Browse Courses</PageTitle>

<h2 class="mb-4">📖 Browse Courses</h2>

@if (departments is not null)
{
    <CourseFilters Departments="departments" OnFiltersChanged="HandleFiltersChanged" />
}

@if (courses is not null)
{
    <p class="text-muted mb-3">Showing @courses.Count course(s)</p>
    <CourseList Courses="courses" />
}

@code {
    [SupplyParameterFromQuery(Name = "department")]
    public int? DepartmentId { get; set; }

    private List<Course>? courses;
    private List<Department>? departments;
    private string? currentSearch;
    private int? currentDepartmentId;

    protected override async Task OnInitializedAsync()
    {
        departments = await CatalogService.GetDepartmentsAsync();
        currentDepartmentId = DepartmentId;
        courses = await CatalogService.GetCoursesAsync(departmentId: currentDepartmentId);
    }

    private async Task HandleFiltersChanged((string? Search, int? DepartmentId) filters)
    {
        currentSearch = filters.Search;
        currentDepartmentId = filters.DepartmentId;
        courses = await CatalogService.GetCoursesAsync(currentSearch, currentDepartmentId);
    }
}

