        <h2 class="mb-4">📝 Enrollment Request</h2>
        <p class="text-muted mb-4">Fill out the form below to submit your enrollment request. You will receive a confirmation email once your request is processed.</p>

        <EnrollmentForm PreselectedCourseId="CourseId" />
    </div>
</div>

@code {
    [SupplyParameterFromQuery(Name = "courseId")]
    public int? CourseId { get; set; }
}

